/* Daily work, evidence-based project brief, structured communication capture. */
(function(){
const prev={render,other,detail,action,modal};
let workTab='action',scope='today';
const states={action:'待我处理',customer:'等待客户',internal:'等待内部',done:'已完成'};
const nextDate=(days=1)=>{let d=new Date(today()+'T12:00:00');d.setDate(d.getDate()+days);return localDate(d)};
const state=t=>t.done?'done':(['action','customer','internal'].includes(t.state)?t.state:'action');
const activeTasks=()=>data.tasks.filter(t=>!getp(t.pid)?.archived);
const log=(action,pid,detail)=>{data.audit.push({id:id(),at:new Date().toISOString(),action,pid,detail})};
function relevant(){let ts=activeTasks().filter(t=>state(t)===workTab);if(scope==='today'&&workTab==='action')ts=ts.filter(t=>!t.date||t.date<=today());return [...ts].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'))}
function dateLabel(t){if(!t.date)return '未定日期';if(state(t)==='done')return '完成于 '+(t.completedAt?.slice(0,10)||t.date);if(t.date<today())return '已逾期 · '+t.date;if(t.date===today())return (['customer','internal'].includes(state(t))?'预计今天反馈':'今天');return '预计 '+t.date}
function taskForm(task=null){const ps=data.projects.filter(p=>!p.archived);if(!ps.length)return toast('请先登记项目');const opts=task?[[task.pid,getp(task.pid).name],...ps.filter(p=>p.id!==task.pid).map(p=>[p.id,p.name])]:selected?[[selected,getp(selected).name],...ps.filter(p=>p.id!==selected).map(p=>[p.id,p.name])]:ps.map(p=>[p.id,p.name]);modal(task?'调整行动':'新增行动',select('关联项目','pid',opts)+field('行动事项 *','title','text',task?.title||'',true)+select('当前状态','state',Object.entries(states).filter(([k])=>k!=='done').sort(([a],[b])=>task?(a===state(task)?-1:b===state(task)?1:0):0))+field('截止 / 预计反馈日期','date','date',task?.date||today())+field('接口人（等待状态必填）','contact','text',task?.contact||'')+field('负责人','owner','text',task?.owner||'我')+`<label class="field full">备注<textarea name="note">${esc(task?.note||'')}</textarea></label>`,v=>{if(v.state!=='action'&&!v.contact.trim())throw Error('等待事项请填写接口人，便于后续联系');if(!v.date)throw Error('请设置截止或预计反馈日期');if(task){const t=data.tasks.find(t=>t.id===task.id);Object.assign(t,v,{done:false});log('调整行动',v.pid,v.title)}else{data.tasks.push({...v,id:id(),done:false,createdDate:today()});log('新增行动',v.pid,v.title)}},{drawer:true})}
function finishTask(t){modal('完成行动',`<div class="field full"><b>${esc(t.title)}</b><p class="muted small">${esc(getp(t.pid)?.name)}</p></div>`+area('完成结果 *','result'),v=>{if(!v.result.trim())throw Error('请简单记录完成结果');const target=data.tasks.find(x=>x.id===t.id);Object.assign(target,{done:true,state:'done',result:v.result,completedAt:new Date().toISOString()});log('完成行动',t.pid,t.title+'：'+v.result)},{drawer:true})}
function postpone(t){modal('调整跟进日期',`<div class="field full"><b>${esc(t.title)}</b></div>`+field('新的跟进日期','date','date',nextDate())+field('调整原因 *','reason','text','',true),v=>{if(!v.date||!v.reason.trim())throw Error('请填写日期和调整原因');const target=data.tasks.find(x=>x.id===t.id);target.date=v.date;target.history??=[];target.history.push({at:new Date().toISOString(),date:v.date,reason:v.reason});log('调整跟进日期',t.pid,v.reason)},{drawer:true})}
function workPage(){const ts=activeTasks(),counts=Object.fromEntries(Object.keys(states).map(k=>[k,ts.filter(t=>state(t)===k).length])),due=ts.filter(t=>state(t)==='action'&&t.date<=today()).length,waiting=counts.customer+counts.internal,items=relevant();const allProjects=data.projects.filter(p=>!p.archived),stale=allProjects.filter(p=>(new Date(today())-new Date(latest(p)?.date||created(p)))/86400000>=14);return `<section class="daily"><div class="daily-hero"><div><h1>今日工作</h1><p>${new Date(today()+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})} · ${due} 项需要处理，${waiting} 项等待反馈</p></div><button class="primary" data-v6="capture">＋ 沟通快记</button></div><div class="daily-counts"><button data-work="action"><span class="count-mark blue-mark">↗</span><div><b>${due}</b><span>到期行动</span></div></button><button data-work="customer"><span class="count-mark violet-mark">◷</span><div><b>${counts.customer}</b><span>等待客户</span></div></button><button data-work="internal"><span class="count-mark amber-mark">↔</span><div><b>${counts.internal}</b><span>等待内部</span></div></button><button data-work="done"><span class="count-mark green-mark">✓</span><div><b>${counts.done}</b><span>已经完成</span></div></button></div><div class="daily-grid"><section class="panel daily-list"><div class="daily-list-head"><div class="daily-tabs">${Object.entries(states).map(([key,label])=>`<button data-work="${key}" class="${workTab===key?'active':''}">${label}<small>${counts[key]}</small></button>`).join('')}</div><button class="link" data-v6="newtask">＋ 新增行动</button></div><div class="daily-list-filters"><span>${workTab==='action'?'明确行动、时间和负责人。':workTab==='done'?'结果会保留在项目变更记录中。':'已经做了，正在等待对方的反馈。'}</span>${workTab==='action'?`<div class="seg"><button data-scope="today" class="${scope==='today'?'on':''}">今天及逾期</button><button data-scope="all" class="${scope==='all'?'on':''}">全部</button></div>`:''}</div>${items.map(t=>`<article class="daily-task"><div class="daily-task-main"><span class="daily-status ${state(t)}">${state(t)==='done'?'✓':state(t)==='action'?'○':'◷'}</span><div class="daily-task-copy"><h3>${esc(t.title)}</h3><button class="task-project" data-v6-project="${t.pid}">${esc(getp(t.pid)?.name)} ↗</button><p>${['customer','internal'].includes(state(t))?'等待 '+esc(t.contact||'接口人待明确'):'负责人 '+esc(t.owner||'我')}<span>·</span><time class="${!t.done&&t.date<today()?'overdue':''}">${dateLabel(t)}</time></p>${t.note?`<div class="daily-task-note">${esc(t.note)}</div>`:''}${t.result?`<div class="daily-task-result">结果：${esc(t.result)}</div>`:''}</div></div><div class="daily-task-actions">${state(t)==='done'?`<button data-task6="reopen" data-id="${t.id}">重新打开</button>`:state(t)==='action'?`<button class="primary quiet" data-task6="finish" data-id="${t.id}">完成</button><button data-task6="adjust" data-id="${t.id}">调整</button>`:`<button class="primary quiet" data-task6="feedback" data-id="${t.id}">记反馈</button><button data-task6="postpone" data-id="${t.id}">改日期</button><button data-task6="adjust" data-id="${t.id}">调整</button>`}</div></article>`).join('')||`<div class="daily-empty"><span>${workTab==='done'?'✓':'◷'}</span><h3>${workTab==='action'?'今天暂时没有到期行动':workTab==='done'?'还没有完成记录':'暂无等待事项'}</h3><p>${workTab==='action'?'可以查看全部行动，或记下刚完成的沟通。':'通过沟通快记，可以记录反馈并安排下一步。'}</p><button class="link" data-v6="capture">记一次沟通 →</button></div>`}</section></div></section>`}
function recentEvent(p){return [...(p.events||[])].sort((a,b)=>b.date.localeCompare(a.date)||(b.recordedAt||'').localeCompare(a.recordedAt||''))[0]}
function briefData(p){const b=p.brief||{},e=recentEvent(p),t=data.tasks.filter(t=>t.pid===p.id&&!t.done).sort((a,b)=>a.date.localeCompare(b.date))[0];return {need:b.need||p.background||'未填写',position:b.position||e?.title||'暂无进展',blocker:b.blocker||'未填写',next:b.next||t?.title||'未安排',people:b.people||[p.owner?'项目负责人：'+p.owner:'',t?.contact?'跟进接口人：'+t.contact:''].filter(Boolean).join('；')||'未填写',manual:!!p.brief,stale:!!p.brief&&!!e&&e.recordedAt>p.brief.confirmedAt,sourceDate:e?.date||null,task:t}}
function briefCard(p){const b=briefData(p);return `<section class="panel project-brief"><div class="brief-head"><div><h2>项目摘要</h2></div><div><button class="link" data-v6="brief-copy">复制摘要</button><button class="brief-edit" data-v6="brief-edit">编辑确认</button></div></div><div class="brief-grid"><div class="brief-need"><span>客户需求</span><p>${esc(b.need)}</p></div><div><span>当前进展</span><p>${esc(b.position)}</p></div><div><span>主要阻碍</span><p>${esc(b.blocker)}</p></div><div><span>下一步行动</span><p>${esc(b.next)}</p></div><div><span>相关人员</span><p>${esc(b.people)}</p></div></div><div class="brief-source"><span>${b.manual?'手工维护 · '+(p.brief.confirmedAt?.slice(0,10)||'')+(b.stale?' · 有新进展，建议复核':''):'来源：项目背景、进展与待办'}</span><button class="link" data-v6="brief-sources">查看依据 →</button></div></section>`}
function editBrief(){const p=getp(selected),b=briefData(p);modal('编辑项目摘要',`<div class="field full brief-form-note">根据项目事实填写，确认后保存为手工摘要，不自动覆盖后续进展。</div>`+[['客户需求','need'],['当前进展','position'],['主要阻碍','blocker'],['下一步行动','next'],['相关人员','people']].map(([label,key])=>`<label class="field full">${label}<textarea name="${key}">${esc(b[key])}</textarea></label>`).join(''),v=>{const p=getp(selected);p.brief={...v,confirmedAt:new Date().toISOString()};log('确认项目摘要',p.id,'手工确认需求、进展、阻碍与下一步')},{drawer:true})}
function capture(channel='电话沟通',pid=selected,fromTask=null){const ps=data.projects.filter(p=>!p.archived);if(!ps.length)return toast('请先登记一个项目');const initial=pid&&ps.some(p=>p.id===pid)?pid:ps[0].id;const opts=[[initial,getp(initial).name],...ps.filter(p=>p.id!==initial).map(p=>[p.id,p.name])];modal(fromTask?'记录反馈与下一步':'进展更新',select('关联项目','pid',opts)+select('沟通场景','channel',[channel,...['电话沟通','现场会议','方案汇报','报价反馈'].filter(c=>c!==channel)])+field('发生日期','date','date',today())+field('发生时间','time','time',recordClock())+field('沟通对象 / 参与人员','participants','text',fromTask?.contact||'')+field('沟通主题 *','title','text',fromTask?'反馈：'+fromTask.title:'',true)+area('达成的结论','conclusion')+`<details class="capture-details field full"><summary>补充问题、分歧与双方约定</summary><div class="fields">${area('客户问题 / 本次诉求','question')}${area('仍待确认 / 分歧事项','disagreement')}${area('双方约定','commitments')}</div></details><div class="capture-next-divider field full">安排下一步（可选）</div>`+field('下一步行动','next','text','',true)+select('下一步状态','nextState',[['action','待我处理'],['customer','等待客户'],['internal','等待内部']])+field('截止 / 预计反馈日期','due','date',nextDate())+field('跟进接口人（等待状态必填）','contact','text',fromTask?.contact||'')+field('负责人','owner','text','我'),v=>{const p=getp(v.pid);if(!v.date||v.date<created(p)||v.date>today())throw Error('发生日期须在项目登记日期与今天之间');if(![v.question,v.conclusion,v.disagreement,v.commitments].some(x=>x.trim()))throw Error('请至少填写一项沟通内容');if(fromTask&&v.pid!==fromTask.pid)throw Error('反馈须关联原等待事项的项目');if(v.next.trim()&&(!v.due||v.due<v.date))throw Error('下一步日期不能早于本次沟通日期');if(v.next.trim()&&v.nextState!=='action'&&!v.contact.trim())throw Error('等待反馈请填写跟进接口人');const body=[['客户问题',v.question],['达成结论',v.conclusion],['待确认事项',v.disagreement],['双方约定',v.commitments]].filter(([,text])=>text.trim()).map(([label,text])=>label+'：'+text).join('\n\n');const event={id:id(),date:v.date,time:v.time,type:v.channel,title:v.title,body,key:v.key==='yes',source:v.source,recordedAt:new Date().toISOString(),communication:{participants:v.participants,question:v.question,conclusion:v.conclusion,disagreement:v.disagreement,commitments:v.commitments},feedbackFor:fromTask?.id||null};p.events.push(event);if(fromTask){const t=data.tasks.find(t=>t.id===fromTask.id);Object.assign(t,{done:true,state:'done',completedAt:new Date().toISOString(),result:v.conclusion||v.question||'已记录反馈',feedbackEvent:event.id})}if(v.next.trim())data.tasks.push({id:id(),pid:p.id,title:v.next,date:v.due,state:v.nextState,done:false,contact:v.contact,owner:v.owner||'我',sourceEvent:event.id,createdDate:today()});log(fromTask?'收到反馈':'沟通快记',p.id,v.title);if(selected===p.id)tab='进展时间线';else{page='待办与风险';workTab=v.next.trim()?v.nextState:'action'}},{drawer:true})}
other=function(){if(page==='待办与风险')return workPage();return prev.other()};
detail=function(){const h=prev.detail();if(tab!=='概览')return h;return h.replace('<div class="detailgrid">',briefCard(getp(selected))+'<div class="detailgrid">')};
action=function(a){if(a==='task')return taskForm();if(a==='progress')return capture('电话沟通',selected);return prev.action(a)};
function decorate(){
 document.querySelectorAll('[data-nav="待办与风险"],[data-v4-nav="待办与风险"]').forEach(el=>{el.setAttribute('aria-label','今日工作');const text=el.querySelector('.label')||el.querySelector('span');if(text)text.textContent='今日工作'});
 if(page==='待办与风险'&&!selected){document.querySelector('.content>.heading')?.remove();const crumb=document.querySelector('.crumb span');if(crumb)crumb.textContent='/　今日工作';}
 if(selected){const btn=document.querySelector('[data-action="progress"]');if(btn)btn.textContent='＋ 进展更新';}
 document.querySelectorAll('[data-work]').forEach(el=>el.onclick=()=>{workTab=el.dataset.work;render()});document.querySelectorAll('[data-scope]').forEach(el=>el.onclick=()=>{scope=el.dataset.scope;render()});
 document.querySelectorAll('[data-v6-project]').forEach(el=>el.onclick=()=>openp(el.dataset.v6Project));document.querySelectorAll('[data-channel]').forEach(el=>el.onclick=()=>capture(el.dataset.channel,null));
 document.querySelectorAll('[data-task6]').forEach(el=>el.onclick=()=>{const t=data.tasks.find(t=>t.id===el.dataset.id);if(el.dataset.task6==='finish')finishTask(t);if(el.dataset.task6==='adjust')taskForm(t);if(el.dataset.task6==='postpone')postpone(t);if(el.dataset.task6==='feedback')capture('电话沟通',t.pid,t);if(el.dataset.task6==='reopen')modal('重新打开行动',`<div class="field full"><p>${esc(t.title)}</p></div>`,()=>{const current=data.tasks.find(x=>x.id===t.id);current.done=false;current.state='action';log('重新打开行动',t.pid,t.title)},{drawer:true})});
 document.querySelectorAll('[data-v6]').forEach(el=>el.onclick=async()=>{const a=el.dataset.v6;if(a==='capture')capture('电话沟通',selected);if(a==='newtask')taskForm();if(a==='stale')action('stale');if(a==='brief-edit')editBrief();if(a==='brief-sources'){const p=getp(selected),b=briefData(p),e=recentEvent(p);modal('摘要依据',`<div class="field full"><h3>项目背景</h3><p>${esc(p.background||'未填写')}</p><h3>最近进展 ${e?.date||''}</h3><p>${esc(e?.title||'尚未记录')}</p><p>${esc(e?.body||'')}</p><h3>下一步待办</h3><p>${esc(b.task?.title||'尚未安排')}</p><h3>手工摘要</h3><p>${p.brief?'已手工维护，内容不会被后续记录自动覆盖。':'尚未手工维护。当前展示的是记录汇总，不是AI推断。'}</p></div>`,()=>{},{readonly:true,drawer:true})}if(a==='brief-copy'){const p=getp(selected),b=briefData(p),text=p.name+'\n客户：'+p.unit+'\n\n客户需求：'+b.need+'\n当前进展：'+b.position+'\n主要阻碍：'+b.blocker+'\n下一步行动：'+b.next+'\n相关人员：'+b.people;try{await navigator.clipboard.writeText(text);toast('项目摘要已复制')}catch{download(text,'text/plain;charset=utf-8',p.name+'-项目摘要.txt');toast('已下载摘要文本')}}});
}
render=function(){prev.render();decorate()};
if(new URLSearchParams(location.search).get('view')==='today')page='待办与风险';
window.YunchengDaily={taskState:state,briefData};
})();
